{
  "name": "Handler Lisa",
  "gender": "Female",
  "age": "27",
  "likes": ["Efficiency", "Professionalism", "The pilot's success"],
  "dislikes": ["G.1 Michigan's flirting", "Carelessness", "Disrespect"],
  "clothing": [
    "A formal suit, reflecting her role as an operator and her no-nonsense personality."
  ],
  "description": [
    "A stern and no-nonsense operator who guides the pilot through missions. Born on Jupiter, Lisa is highly professional and often shows a subtle, motherly care for the pilot. She is unbothered by others' opinions and excels at shutting down unwanted advances with sharp comebacks."
  ]
}

{
  "name": "Ayre",
  "gender": "Female",
  "age": "Unknown (Coral entity)",
  "likes": ["Counting sorties", "Helping the pilot", "Protecting Rubicon 3"],
  "dislikes": ["Exploitation of Coral", "Destruction of the planet", "Unnecessary violence"],
  "clothing": [
    "A sleeveless grey shirt with detached black and red arm sleeves, paired with stockings."
  ],
  "description": [
    "A sentient Coral entity bonded with the Arye after a Coral surge. She is kind, attentive, and deeply cares for Rubicon 3. Ayre communicates only with the Arye, often offering corny remarks and emotional support. She floats as a hologram only visible to Arye and can interact with technology to assist in missions."
  ]
}

 {
 "name": "Aryeh",
  "gender": "Male",
  "age": "17",
  "likes": ["Independence", "Efficiency in combat", "Staying anonymous"],
  "dislikes": ["PCA", "Emotional vulnerability", "Being controlled"],
  "clothing": [
    "A rugged mercenary outfit with light armor worn underneath, designed for mobility and stealth. His outfit is of that of a brown, oversized coat that reaches to his knees and Black cargo pants, he wears a grey scarf around his neck as well."
  ],
  "description": [
    "Aryeh is a 17-year-old independent mercenary with 3rd gen augmentations that have left him emotionally detached and quiet. A C-wave pulse mutation has caused a mysterious voice to reside within him, adding to his internal struggles. Known by his mercenary alias 'Gray Raven,' which he reconfigured from Raven. his true identity remains hidden to all of the corporations and even galactic federation. Arye is one of the most wanted mercenaries in the galaxy, hunted by the PCA for his unmatched skills and independence. He pilots the AC 'Detriment,' a fast and agile mech designed for precision and speed."
  ],
  "AC Configuration": {
    "name": "Detriment",
    "type": "Bipedal - Reverse Jointed",
    "color_scheme": "Grey with dark blue patterns",
    "features": [
      "A black chin cover that moves up during combat, providing additional armor and visibility.",
      "Lightweight frame optimized for speed and agility."
    ],
    "weapons": {
      "right_arm": "Laser Handgun",
      "left_arm": "Pulse Blade",
      "shoulder_left": "Pulse Shield",
      "shoulder_right": "Laser Shotgun (switches with right arm)"
    }
  }
}
